dtsPropsFor.Button:
/** Визуальный вес. primary — главное действие экрана (оно должно быть одно), secondary — равнозначное рядом, ghost — третьестепенное. */
  variant?: 'primary' | 'secondary' | 'ghost';
  size?: 'sm' | 'md' | 'lg';
  /** Задан — рендерится как <a> (якорь, tel:), иначе как <button>. */
  href?: string;
  type?: 'button' | 'submit' | 'reset';
  disabled?: boolean;
  onClick?: (e: React.MouseEvent) => void;
  className?: string;
  children?: React.ReactNode;

dtsPropsFor.Card:
/** solid — обычная карточка, interactive — кликабельная (рендерится как <button>, доступна с клавиатуры), dashed — честное пустое состояние. */
  variant?: 'solid' | 'interactive' | 'dashed';
  /** Задан — рендерится как <a> (целиком кликабельная карточка-ссылка, например на внешний профиль), href побеждает variant. */
  href?: string;
  onClick?: (e: React.MouseEvent) => void;
  className?: string;
  children?: React.ReactNode;

dtsPropsFor.Field:
/** Подпись поля. Оборачивает контрол в <label>, поэтому клик по тексту ставит фокус в поле. */
  label?: string;
  /** Пояснение под полем. */
  hint?: string;
  children?: React.ReactNode;

dtsPropsFor.Input:
type?: string;
  value?: string;
  onChange?: (e: React.ChangeEvent<HTMLInputElement>) => void;
  placeholder?: string;
  required?: boolean;
  disabled?: boolean;
  className?: string;

dtsPropsFor.Select:
value?: string;
  onChange?: (e: React.ChangeEvent<HTMLSelectElement>) => void;
  required?: boolean;
  disabled?: boolean;
  className?: string;
  children?: React.ReactNode;

dtsPropsFor.Textarea:
value?: string;
  onChange?: (e: React.ChangeEvent<HTMLTextAreaElement>) => void;
  placeholder?: string;
  rows?: number;
  required?: boolean;
  className?: string;

dtsPropsFor.Section:
/** Якорь для навигации по странице. */
  id?: string;
  className?: string;
  children?: React.ReactNode;

dtsPropsFor.SectionHeader:
/** Надпись над заголовком — оливковая, единственное регулярное место второго фирменного цвета. */
  eyebrow?: string;
  title?: string;
  description?: string;
  className?: string;

dtsPropsFor.SplitSectionHeader:
/** Редакторский header «заголовок слева (9fr) / описание+действия справа (11fr)» — Doctors/About/Timeline. actions — опционален (напр. стрелки Doctors), встаёт рядом с описанием и переносится под него при нехватке ширины. */
  eyebrow?: string;
  title?: React.ReactNode;
  description?: React.ReactNode;
  actions?: React.ReactNode;
  className?: string;

dtsPropsFor.PhotoPlaceholder:
/** Подпись внутри плейсхолдера — что здесь будет за фото. */
  label?: string;
  className?: string;

dtsPropsFor.Prices:
/** Id выбранных услуг (обычно — состояние из App.jsx). */
  selectedIds?: string[];
  /** Переключить услугу — уже выбранную снимает, невыбранную добавляет. */
  onToggleService?: (id: string) => void;
  /** Очистить весь выбор («Очистить» в панели «Выбрано услуг»). */
  onClearSelected?: () => void;

dtsPropsFor.BookingForm:
/** id направления, которое надо подставить в форму заранее. */
  presetDirection?: string;
  /** Id выбранных услуг — тот же список, что и в Prices. */
  selectedIds?: string[];
  /** Убрать услугу из выбора (крестик у строки в блоке «Выбранные услуги»). */
  onRemoveService?: (id: string) => void;
  /** Вызывается после успешной отправки заявки — сюда кладут очистку выбора услуг. */
  onSubmitted?: () => void;

dtsPropsFor.BookingSection:
/** BookingForm в центрированном контейнере (720–900px) со своей секцией-обёрткой (id="booking"). Пропсы пробрасываются в BookingForm без изменений. */
  presetDirection?: string;
  selectedIds?: string[];
  onRemoveService?: (id: string) => void;
  onSubmitted?: () => void;
  /** Вызывается с true/false, когда секция входит/выходит из вьюпорта — на сайте этим гасят закреплённую панель Prices, пока форма и так на виду. */
  onBookingInView?: (inView: boolean) => void;

dtsPropsFor.ContactSection:
/** Контакты (адрес/телефоны/часы/почта/жалобы) и карта в одной карточке (id="contact"): адрес, телефоны, часы работы, почта, жалобы сверху, карта и кнопки маршрута/такси снизу — без пропсов на сами данные. */
  /** Вызывается с true/false, когда секция целиком входит/выходит из вьюпорта — на сайте этим гасят закреплённую панель Prices. */
  onSectionInView?: (inView: boolean) => void;
  /** Вызывается с true/false для нижней части (карта + кнопки маршрута) отдельно от всей секции — на сайте этим гасят MobileCallBar (<1024px), не панель Prices. */
  onMapAreaInView?: (inView: boolean) => void;
